uestions let us know'=>'ex.: Agradecemos sua preferência. Se você tiver alguma dúvida, fale conosco','e.g. Your Address'=>'ex.: Seu endereço','e.g. your@domain.com'=>'ex.: seu@domínio.com','here'=>'aqui','or'=>'ou','reCaptcha Site Secret'=>'Segredo do site reCaptcha','reCaptcha Site Key'=>'Chave do site reCaptcha']];